class Parallellogram:

    def __init__(self, a, b, h):
        self.kant1 = a
        self.basKant = b
        self.hojd = h

    def area(self):
        return self.hojd*self.basKant

    def omkrets(self):
        return 2*(self.kant1+self.basKant)


class Rektangel(Parallellogram):

    def __init__(self, a, b):
        super().__init__(a, b, a)

    def area(self):
        # Egentligen onödigt, vi kan ärva metoden!
        return self.kant1*self.basKant


class Kvadrat(Rektangel):

    def __init__(self, a):
        super().__init__(a, a)
